export function findNationalEnergyRule({ provider = "", date = new Date() } = {}) {
  const needle = normalize(provider);
  if (!needle) return null;
  const when = date instanceof Date ? date : new Date(date);
  return NATIONAL_ENERGY_CATALOG.find((rule) => rule.automatic && Number.isFinite(rule.ratePerKwh) && matchesProvider(rule, needle) && isCurrent(rule, when)) || null;
}

export function listNationalEnergyProviders() { return NATIONAL_ENERGY_CATALOG.filter((rule) => rule.automatic).map((rule) => rule.provider); }
function matchesProvider(rule, needle) { return [rule.provider, ...(rule.providerAliases || [])].some((value) => { const candidate = normalize(value); return candidate === needle || candidate.includes(needle) || needle.includes(candidate); }); }
function isCurrent(rule, date) { if (Number.isNaN(date.getTime())) return false; const day = date.toISOString().slice(0,10); return (!rule.validFrom || day >= rule.validFrom) && (!rule.validUntil || day <= rule.validUntil); }
function normalize(value) { return String(value || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-zA-Z0-9]+/g, " ").trim().toLowerCase(); }
